// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title OrderBookDEX
 * @author Expert Solidity Engineer
 * @notice A non-custodial on-chain limit order book DEX for ERC20 token pairs.
 * This contract is designed for EVM-compatible chains like Camp (BaseCAMP).
 * Features:
 * - Limit orders (buy/sell) with price-time priority.
 * - Non-custodial token management via internal balances.
 * - Maker/Taker fee model.
 * - Admin-managed pair listings and pausing.
 * - Reentrancy protection.
 */
contract OrderBookDEX is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ----------- Enums and Structs -----------

    enum Side { BUY, SELL }

    struct Pair {
        IERC20 baseToken;
        IERC20 quoteToken;
        bool paused;
    }

    struct Order {
        bytes32 id;
        address user;
        uint256 pairId;
        Side side;
        uint256 price; // In quote tokens per base token
        uint256 amount; // In base token
        uint256 filled; // In base token
        bytes32 nextOrder; // Pointer to next order at the same price level
        bytes32 prevOrder; // Pointer to previous order at the same price level
    }

    struct PriceLevel {
        bytes32 orderHead; // First order in the queue
        bytes32 orderTail; // Last order in the queue
        uint256 nextPrice; // Pointer to the next price level in the sorted list
        uint256 prevPrice; // Pointer to the previous price level in the sorted list
    }

    // ----------- State Variables -----------

    Pair[] public pairs;
    mapping(address => mapping(address => bool)) public pairExists;

    mapping(bytes32 => Order) public orders;
    mapping(address => mapping(uint256 => bytes32[])) private _userOpenOrders;

    // Per-pair order book storage: pairId => price => PriceLevel
    mapping(uint256 => mapping(uint256 => PriceLevel)) private _buyBook;
    mapping(uint256 => mapping(uint256 => PriceLevel)) private _sellBook;
    // pairId => best price (head of the price level linked list)
    mapping(uint256 => uint256) public bestBuyPrice;  // Highest buy price
    mapping(uint256 => uint256) public bestSellPrice; // Lowest sell price

    // User balances
    mapping(address => mapping(IERC20 => uint256)) public balances;
    mapping(address => mapping(IERC20 => uint256)) public lockedBalances;

    // Fees and treasury
    address public treasury;
    uint256 public makerFeeBps; // In basis points (1 BPS = 0.01%)
    uint256 public takerFeeBps;
    uint256 private constant BPS_DIVISOR = 10000;
    uint256 private constant MAX_MATCHES_PER_TX = 30;

    // ----------- Events -----------

    event PairListed(uint256 indexed pairId, address indexed baseToken, address indexed quoteToken);
    event PairPaused(uint256 indexed pairId, bool isPaused);
    event FeesUpdated(uint256 makerFeeBps, uint256 takerFeeBps);
    event TreasuryUpdated(address indexed newTreasury);

    event Deposit(address indexed user, IERC20 indexed token, uint256 amount);
    event Withdraw(address indexed user, IERC20 indexed token, uint256 amount);

    event OrderPlaced(bytes32 indexed orderId, address indexed user, uint256 indexed pairId, Side side, uint256 price, uint256 amount);
    event OrderCancelled(bytes32 indexed orderId);
    event OrderMatched(
        bytes32 indexed takerOrderId,
        bytes32 indexed makerOrderId,
        uint256 amountBase,
        uint256 amountQuote,
        uint256 makerFee,
        uint256 takerFee
    );

    // ----------- Modifiers -----------

    modifier whenPairNotPaused(uint256 pairId) {
        require(pairId < pairs.length, "OrderBookDEX: Pair does not exist");
        require(!pairs[pairId].paused, "OrderBookDEX: Pair is paused");
        _;
    }

    // ----------- Constructor -----------

    constructor(address _initialTreasury, uint256 _initialMakerFeeBps, uint256 _initialTakerFeeBps) {
        require(_initialTreasury != address(0), "OrderBookDEX: Treasury cannot be zero address");
        require(_initialMakerFeeBps < BPS_DIVISOR && _initialTakerFeeBps < BPS_DIVISOR, "OrderBookDEX: Fee too high");
        treasury = _initialTreasury;
        makerFeeBps = _initialMakerFeeBps;
        takerFeeBps = _initialTakerFeeBps;
    }

    // ----------- Admin Functions -----------

    function listPair(IERC20 baseToken, IERC20 quoteToken) external onlyOwner {
        require(address(baseToken) != address(0) && address(quoteToken) != address(0), "OrderBookDEX: Zero address token");
        require(address(baseToken) != address(quoteToken), "OrderBookDEX: Tokens cannot be the same");
        require(!pairExists[address(baseToken)][address(quoteToken)], "OrderBookDEX: Pair already exists");

        uint256 pairId = pairs.length;
        pairs.push(Pair({
            baseToken: baseToken,
            quoteToken: quoteToken,
            paused: false
        }));
        pairExists[address(baseToken)][address(quoteToken)] = true;

        emit PairListed(pairId, address(baseToken), address(quoteToken));
    }

    function setPairPaused(uint256 pairId, bool isPaused) external onlyOwner {
        require(pairId < pairs.length, "OrderBookDEX: Pair does not exist");
        pairs[pairId].paused = isPaused;
        emit PairPaused(pairId, isPaused);
    }

    function setFees(uint256 _newMakerFeeBps, uint256 _newTakerFeeBps) external onlyOwner {
        require(_newMakerFeeBps < BPS_DIVISOR && _newTakerFeeBps < BPS_DIVISOR, "OrderBookDEX: Fee too high");
        makerFeeBps = _newMakerFeeBps;
        takerFeeBps = _newTakerFeeBps;
        emit FeesUpdated(makerFeeBps, takerFeeBps);
    }

    function setTreasury(address _newTreasury) external onlyOwner {
        require(_newTreasury != address(0), "OrderBookDEX: Treasury cannot be zero address");
        treasury = _newTreasury;
        emit TreasuryUpdated(_newTreasury);
    }

    // ----------- Deposit and Withdraw -----------

    function deposit(IERC20 token, uint256 amount) external nonReentrant {
        require(amount > 0, "OrderBookDEX: Amount must be positive");
        balances[msg.sender][token] += amount;
        token.safeTransferFrom(msg.sender, address(this), amount);
        emit Deposit(msg.sender, token, amount);
    }

    function withdraw(IERC20 token, uint256 amount) external nonReentrant {
        require(amount > 0, "OrderBookDEX: Amount must be positive");
        uint256 availableBalance = balances[msg.sender][token] - lockedBalances[msg.sender][token];
        require(amount <= availableBalance, "OrderBookDEX: Insufficient available balance");
        balances[msg.sender][token] -= amount;
        token.safeTransfer(msg.sender, amount);
        emit Withdraw(msg.sender, token, amount);
    }

    // ----------- Core DEX Functions -----------

    function placeOrder(uint256 pairId, Side side, uint256 price, uint256 amount)
        external
        nonReentrant
        whenPairNotPaused(pairId)
        returns (bytes32)
    {
        require(price > 0, "OrderBookDEX: Price must be positive");
        require(amount > 0, "OrderBookDEX: Amount must be positive");

        Pair storage pair = pairs[pairId];
        IERC20 tokenToLock = side == Side.BUY ? pair.quoteToken : pair.baseToken;
        uint256 amountToLock = side == Side.BUY ? (amount * price) : amount;

        uint256 availableBalance = balances[msg.sender][tokenToLock] - lockedBalances[msg.sender][tokenToLock];
        require(amountToLock <= availableBalance, "OrderBookDEX: Insufficient balance to place order");

        lockedBalances[msg.sender][tokenToLock] += amountToLock;

        bytes32 orderId = _generateOrderId(msg.sender, pairId, side, price, amount);
        Order memory newOrder = Order({
            id: orderId,
            user: msg.sender,
            pairId: pairId,
            side: side,
            price: price,
            amount: amount,
            filled: 0,
            nextOrder: bytes32(0),
            prevOrder: bytes32(0)
        });

        uint256 amountLeft = _tryMatch(newOrder);

        if (amountLeft > 0) {
            newOrder.amount = amountLeft; // Only remaining amount becomes a maker order
            orders[orderId] = newOrder;
            _addToBook(orderId);
            _addUserOrder(msg.sender, pairId, orderId);

            // Adjust locked balance. The part of the order that was filled is no longer locked.
            uint256 filledAmount = amount - amountLeft;
            uint256 amountToUnlock = side == Side.BUY ? (filledAmount * price) : filledAmount;
            lockedBalances[msg.sender][tokenToLock] -= amountToUnlock;
        } else {
            // Full match, no need to add to book. Unlock the full amount that was originally locked for this order.
            lockedBalances[msg.sender][tokenToLock] -= amountToLock;
        }

        emit OrderPlaced(orderId, msg.sender, pairId, side, price, amount);
        return orderId;
    }

    function cancelOrder(bytes32 orderId) external nonReentrant {
        Order storage order = orders[orderId];
        require(order.id != bytes32(0), "OrderBookDEX: Order does not exist");
        require(order.user == msg.sender, "OrderBookDEX: Not order owner");

        _removeFromBook(orderId);
        _removeUserOrder(order.user, order.pairId, orderId);

        Pair storage pair = pairs[order.pairId];
        uint256 amountRemaining = order.amount - order.filled;
        uint256 lockedAmountRemaining;

        if (order.side == Side.BUY) {
            lockedAmountRemaining = amountRemaining * order.price;
            lockedBalances[msg.sender][pair.quoteToken] -= lockedAmountRemaining;
        } else { // SELL
            lockedAmountRemaining = amountRemaining;
            lockedBalances[msg.sender][pair.baseToken] -= lockedAmountRemaining;
        }

        delete orders[orderId];
        emit OrderCancelled(orderId);
    }

    // ----------- Internal Matching and Book Logic -----------

    function _tryMatch(Order memory takerOrder) internal returns (uint256) {
        uint256 amountToFill = takerOrder.amount;
        Pair storage pair = pairs[takerOrder.pairId];

        for (uint256 i = 0; i < MAX_MATCHES_PER_TX && amountToFill > 0; ++i) {
            bytes32 makerOrderId = _getBestMakerOrder(takerOrder.pairId, takerOrder.side);
            if (makerOrderId == bytes32(0)) break; // No more orders to match against

            Order storage makerOrder = orders[makerOrderId];
            bool pricesCross = takerOrder.side == Side.BUY
                ? takerOrder.price >= makerOrder.price
                : takerOrder.price <= makerOrder.price;

            if (!pricesCross) break;

            uint256 makerAmountAvailable = makerOrder.amount - makerOrder.filled;
            uint256 fillAmountBase = amountToFill > makerAmountAvailable ? makerAmountAvailable : amountToFill;
            uint256 fillAmountQuote = fillAmountBase * makerOrder.price;

            uint256 takerFee = (fillAmountQuote * takerFeeBps) / BPS_DIVISOR;
            uint256 makerFee = (fillAmountQuote * makerFeeBps) / BPS_DIVISOR;

            address taker = takerOrder.user;
            address maker = makerOrder.user;

            if (takerOrder.side == Side.BUY) { // Taker is BUYER, Maker is SELLER
                balances[taker][pair.quoteToken] -= (fillAmountQuote + takerFee);
                balances[taker][pair.baseToken] += fillAmountBase;
                balances[maker][pair.baseToken] -= fillAmountBase;
                balances[maker][pair.quoteToken] += (fillAmountQuote - makerFee);
                lockedBalances[maker][pair.baseToken] -= fillAmountBase;
            } else { // Taker is SELLER, Maker is BUYER
                balances[taker][pair.baseToken] -= fillAmountBase;
                balances[taker][pair.quoteToken] += (fillAmountQuote - takerFee);
                balances[maker][pair.quoteToken] -= fillAmountQuote;
                balances[maker][pair.baseToken] += fillAmountBase;
                lockedBalances[maker][pair.quoteToken] -= fillAmountQuote;
            }

            balances[treasury][pair.quoteToken] += (takerFee + makerFee);

            amountToFill -= fillAmountBase;
            takerOrder.filled += fillAmountBase;
            makerOrder.filled += fillAmountBase;

            emit OrderMatched(takerOrder.id, makerOrderId, fillAmountBase, fillAmountQuote, makerFee, takerFee);

            if (makerOrder.filled >= makerOrder.amount) {
                _removeFromBook(makerOrderId);
                _removeUserOrder(makerOrder.user, makerOrder.pairId, makerOrderId);
                delete orders[makerOrderId];
            }
        }
        return amountToFill;
    }

    function _getBestMakerOrder(uint256 pairId, Side takerSide) internal view returns (bytes32) {
        if (takerSide == Side.BUY) { // Taker buys, needs to match against sell book (lowest price)
            uint256 price = bestSellPrice[pairId];
            if (price == 0) return bytes32(0);
            return _sellBook[pairId][price].orderHead;
        } else { // Taker sells, needs to match against buy book (highest price)
            uint256 price = bestBuyPrice[pairId];
            if (price == 0) return bytes32(0);
            return _buyBook[pairId][price].orderHead;
        }
    }

    function _addToBook(bytes32 orderId) internal {
        Order storage order = orders[orderId];
        mapping(uint256 => mapping(uint256 => PriceLevel)) storage book = order.side == Side.BUY ? _buyBook : _sellBook;
        PriceLevel storage level = book[order.pairId][order.price];

        if (level.orderHead == bytes32(0)) { // New price level
            level.orderHead = orderId;
            level.orderTail = orderId;
            _addPriceLevel(order.pairId, order.price, order.side);
        } else { // Existing price level, add to end of queue (time priority)
            bytes32 oldTailId = level.orderTail;
            orders[oldTailId].nextOrder = orderId;
            order.prevOrder = oldTailId;
            level.orderTail = orderId;
        }
    }

    function _removeFromBook(bytes32 orderId) internal {
        Order storage order = orders[orderId];
        mapping(uint256 => mapping(uint256 => PriceLevel)) storage book = order.side == Side.BUY ? _buyBook : _sellBook;
        PriceLevel storage level = book[order.pairId][order.price];

        if (order.prevOrder != bytes32(0)) orders[order.prevOrder].nextOrder = order.nextOrder;
        if (order.nextOrder != bytes32(0)) orders[order.nextOrder].prevOrder = order.prevOrder;

        if (level.orderHead == orderId) level.orderHead = order.nextOrder;
        if (level.orderTail == orderId) level.orderTail = order.prevOrder;

        if (level.orderHead == bytes32(0)) {
            _removePriceLevel(order.pairId, order.price, order.side);
        }
    }

    function _addPriceLevel(uint256 pairId, uint256 price, Side side) internal {
        if (side == Side.BUY) {
            mapping(uint256 => PriceLevel) storage book = _buyBook[pairId];
            uint256 bestPrice = bestBuyPrice[pairId];

            if (bestPrice == 0 || price > bestPrice) { // New best price
                if (bestPrice != 0) {
                    book[bestPrice].nextPrice = price;
                }
                book[price].prevPrice = bestPrice;
                bestBuyPrice[pairId] = price;
            } else { // Insert into sorted list
                uint256 current = bestPrice;
                // Traverse down the list of descending prices to find the insertion point
                while (book[current].prevPrice != 0 && price < book[current].prevPrice) {
                    current = book[current].prevPrice;
                }
                // Insert 'price' between 'current' and 'prev'
                uint256 prev = book[current].prevPrice;
                book[current].prevPrice = price;
                book[price].nextPrice = current;
                book[price].prevPrice = prev;
                if (prev != 0) {
                    book[prev].nextPrice = price;
                }
            }
        } else { // side == Side.SELL
            mapping(uint256 => PriceLevel) storage book = _sellBook[pairId];
            uint256 bestPrice = bestSellPrice[pairId];

            if (bestPrice == 0 || price < bestPrice) { // New best price
                if (bestPrice != 0) {
                    book[bestPrice].nextPrice = price;
                }
                book[price].prevPrice = bestPrice;
                bestSellPrice[pairId] = price;
            } else { // Insert into sorted list
                uint256 current = bestPrice;
                // Traverse up the list of ascending prices to find the insertion point
                while (book[current].prevPrice != 0 && price > book[current].prevPrice) {
                    current = book[current].prevPrice;
                }
                // Insert 'price' between 'current' and 'prev'
                uint256 prev = book[current].prevPrice;
                book[current].prevPrice = price;
                book[price].nextPrice = current;
                book[price].prevPrice = prev;
                if (prev != 0) {
                    book[prev].nextPrice = price;
                }
            }
        }
    }

    function _removePriceLevel(uint256 pairId, uint256 price, Side side) internal {
        mapping(uint256 => mapping(uint256 => PriceLevel)) storage book = side == Side.BUY ? _buyBook : _sellBook;
        PriceLevel storage level = book[pairId][price];

        if (level.prevPrice != 0) book[pairId][level.prevPrice].nextPrice = level.nextPrice;
        if (level.nextPrice != 0) book[pairId][level.nextPrice].prevPrice = level.prevPrice;

        if (side == Side.BUY && bestBuyPrice[pairId] == price) bestBuyPrice[pairId] = level.prevPrice;
        if (side == Side.SELL && bestSellPrice[pairId] == price) bestSellPrice[pairId] = level.prevPrice;

        delete book[pairId][price];
    }

    function _generateOrderId(address user, uint256 pairId, Side side, uint256 price, uint256 amount)
        internal view returns (bytes32)
    {
        return keccak256(abi.encodePacked(user, pairId, side, price, amount, block.timestamp, msg.sender));
    }

    function _addUserOrder(address user, uint256 pairId, bytes32 orderId) internal {
        _userOpenOrders[user][pairId].push(orderId);
    }

    function _removeUserOrder(address user, uint256 pairId, bytes32 orderId) internal {
        bytes32[] storage userOrders = _userOpenOrders[user][pairId];
        for (uint i = 0; i < userOrders.length; i++) {
            if (userOrders[i] == orderId) {
                userOrders[i] = userOrders[userOrders.length - 1];
                userOrders.pop();
                break;
            }
        }
    }

    // ----------- View Functions -----------

    function getAvailableBalance(address user, IERC20 token) external view returns (uint256) {
        return balances[user][token] - lockedBalances[user][token];
    }

    function getUserOpenOrderIds(address user, uint256 pairId) external view returns (bytes32[] memory) {
        return _userOpenOrders[user][pairId];
    }

    struct OrderBookLevelView {
        uint256 price;
        uint256 totalAmount;
    }

    function _getSideSnapshot(
        uint256 pairId,
        mapping(uint256 => mapping(uint256 => PriceLevel)) storage book,
        uint256 startPrice,
        uint256 count
    ) private view returns (OrderBookLevelView[] memory) {
        OrderBookLevelView[] memory levels = new OrderBookLevelView[](count > 0 ? count : 1);
        uint256 currentPrice = startPrice;

        uint levelsFound = 0;
        for (uint i = 0; i < count; ++i) {
            if (currentPrice == 0) break;

            bytes32 orderId = book[pairId][currentPrice].orderHead;
            uint256 totalAmountAtPrice;
            while (orderId != bytes32(0)) {
                Order storage order = orders[orderId];
                totalAmountAtPrice += (order.amount - order.filled);
                orderId = order.nextOrder;
            }

            levels[i] = OrderBookLevelView({ price: currentPrice, totalAmount: totalAmountAtPrice });
            levelsFound++;
            currentPrice = book[pairId][currentPrice].prevPrice;
        }

        if (levelsFound < levels.length) {
            OrderBookLevelView[] memory resizedLevels = new OrderBookLevelView[](levelsFound);
            for (uint j = 0; j < levelsFound; ++j) {
                resizedLevels[j] = levels[j];
            }
            return resizedLevels;
        }

        return levels;
    }

    function getOrderBookSnapshot(uint256 pairId, Side side, uint256 count) 
        external 
        view 
        returns (OrderBookLevelView[] memory)
    {
        require(pairId < pairs.length, "OrderBookDEX: Pair does not exist");

        if (side == Side.BUY) {
            return _getSideSnapshot(pairId, _buyBook, bestBuyPrice[pairId], count);
        } else {
            return _getSideSnapshot(pairId, _sellBook, bestSellPrice[pairId], count);
        }
    }
}

